alter table public.current_health_assessments
  add column if not exists domain_answers jsonb not null default '{}'::jsonb;

alter table public.shop_products
  add column if not exists primary_category text,
  add column if not exists for_symptoms jsonb not null default '[]'::jsonb,
  add column if not exists pacifies text[] not null default '{}',
  add column if not exists may_aggravate text[] not null default '{}';

alter table public.shop_products
  add constraint shop_products_for_symptoms_is_array
  check (jsonb_typeof(for_symptoms) = 'array');

