ha"],"may_aggravate":["Pitta"]},{"name":"Brahmi Taila","primary_category":"Stress & Sleep","for_symptoms":[{"domain":"sleep","symptom":"Light, disturbed"}],"pacifies":["Vata","Pitta"],"may_aggravate":[]},{"name":"Bhringraj Taila","primary_category":"Skin & Hair","for_symptoms":[{"domain":"sleep","symptom":"Light, disturbed"}],"pacifies":["Pitta","Vata"],"may_aggravate":[]},{"name":"Neelibhringadi Taila","primary_category":"Skin & Hair","for_symptoms":[{"domain":"sleep","symptom":"Light, disturbed"}],"pacifies":["Pitta","Vata"],"may_aggravate":[]},{"name":"Bala Taila","primary_category":"Joint & Muscle Health","for_symptoms":[{"domain":"stool","symptom":"Hard, dry, difficult"},{"domain":"urine","symptom":"Infrequent, reduced"}],"pacifies":["Vata"],"may_aggravate":["Kapha"]},{"name":"Ksheerabala Taila","primary_category":"Joint & Muscle Health","for_symptoms":[{"domain":"stool","symptom":"Hard, dry, difficult"},{"domain":"sleep","symptom":"Light, disturbed"}],"pacifies":["Vata"],"may_aggravate":["Kapha"]},{"name":"Anu Taila","primary_category":"Respiratory Health","for_symptoms":[{"domain":"sleep","symptom":"Long, heavy"}],"pacifies":["Vata","Kapha"],"may_aggravate":["Pitta"]},{"name":"Jatamansi Taila","primary_category":"Stress & Sleep","for_symptoms":[{"domain":"sleep","symptom":"Light, disturbed"}],"pacifies":["Vata","Pitta"],"may_aggravate":["Kapha"]}]}$inventory$::jsonb)->'products')
    with ordinality as entry(item, ordinal)
), prepared as (
  select
    trim(both '-' from regexp_replace(regexp_replace(lower(item->>'name'), '[^a-z0-9]+', '-', 'g'), '-+', '-', 'g')) as id,
    item->>'name' as name,
    item->>'primary_category' as primary_category,
    item->'for_symptoms' as for_symptoms,
    array(select jsonb_array_elements_text(item->'pacifies')) as pacifies,
    array(select jsonb_array_elements_text(item->'may_aggravate')) as may_aggravate,
    sort_order
  from inventory
)
insert into public.shop_products (
  id, name, weight, price, mrp, icon, categories, tags, description, rating, rating_count,
  active, sort_order, primary_category, for_symptoms, pacifies, may_aggravate, updated_at
)
select
  id,
  name,
  case
    when lower(name) like '%taila%' or lower(name) like '%oil%' then '200 ml'
    when lower(name) like '%arishta%' or lower(name) like '%asava%' then '450 ml'
    when lower(name) like '%chyawanprash%' then '500 g'
    when lower(name) like '%churna%' then '100 g'
    else '500 mg · 60 tablets'
  end,
  299 + ((sort_order % 5) * 50),
  399 + ((sort_order % 5) * 50),
  upper(left(name, 1)),
  array[primary_category],
  array[lower(replace(replace(primary_category, ' & ', '-'), ' ', '-'))],
  name || ' is an Ayurvedic formulation selected to support ' || lower(primary_category) || '.',
  4.5 + ((sort_order % 4)::numeric / 10),
  120 + (sort_order * 9),
  true,
  sort_order,
  primary_category,
  for_symptoms,
  pacifies,
  may_aggravate,
  now()
from prepared
on conflict (id) do update set
  name = excluded.name,
  categories = excluded.categories,
  primary_category = excluded.primary_category,
  for_symptoms = excluded.for_symptoms,
  pacifies = excluded.pacifies,
  may_aggravate = excluded.may_aggravate,
  active = true,
  sort_order = excluded.sort_order,
  tags = array_remove(public.shop_products.tags, 'recommended'),
  updated_at = now();

update public.shop_products
set
  primary_category = coalesce(primary_category, categories[1], 'General Wellness'),
  tags = array_remove(tags, 'recommended'),
  updated_at = now();

alter table public.shop_products
  alter column primary_category set not null;

create table public.supplement_recommendation_plans (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  current_health_assessment_id uuid not null unique references public.current_health_assessments(id) on delete cascade,
  prakriti jsonb not null,
  vikruti text not null,
  symptoms jsonb not null default '[]'::jsonb,
  domain_answers jsonb not null default '{}'::jsonb,
  filtered_inventory jsonb not null default '[]'::jsonb,
  recommendations jsonb not null,
  model text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint supplement_recommendations_is_object check (jsonb_typeof(recommendations) = 'object'),
  constraint supplement_prakriti_is_object check (jsonb_typeof(prakriti) = 'object'),
  constraint supplement_symptoms_is_array check (jsonb_typeof(symptoms) = 'array'),
  constraint supplement_domain_answers_is_object check (jsonb_typeof(domain_answers) = 'object'),
  constraint supplement_filtered_inventory_is_array check (jsonb_typeof(filtered_inventory) = 'array')
);

create index supplement_recommendation_plans_user_created_idx
  on public.supplement_recommendation_plans (user_id, created_at desc);

alter table public.supplement_recommendation_plans enable row level security;
revoke all on table public.supplement_recommendation_plans from anon, authenticated;
grant select, insert, update on table public.supplement_recommendation_plans to authenticated;

create policy "Users can read their own supplement recommendations"
on public.supplement_recommendation_plans for select to authenticated
using ((select auth.uid()) = user_id);

create policy "Users can create supplement recommendations for their own assessments"
on public.supplement_recommendation_plans for insert to authenticated
with check (
  (select auth.uid()) = user_id
  and exists (
    select 1
    from public.current_health_assessments assessment
    where assessment.id = current_health_assessment_id
      and assessment.user_id = (select auth.uid())
  )
);

create policy "Users can update their own supplement recommendations"
on public.supplement_recommendation_plans for update to authenticated
using ((select auth.uid()) = user_id)
with check ((select auth.uid()) = user_id);
